function TypingQuote({
  text = `"Every approach is a guess. You can't see how they're feeling. They can't signal you to wait. So you interrupt, and the moment breaks."`,
  className = "",
}: {
  text?: string;
  className?: string;
}) {
  const [displayedText, setDisplayedText] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const [isDone, setIsDone] = useState(false);
  const containerRef = useRef<HTMLParagraphElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !isTyping && !isDone) {
          setIsTyping(true);
        }
      },
      { threshold: 0.25 }
    );

    if (containerRef.current) {
      observer.observe(containerRef.current);
    }

    return () => observer.disconnect();
  }, [isTyping, isDone]);

  useEffect(() => {
    if (!isTyping || isDone) return;

    let currentIndex = 0;
    const interval = setInterval(() => {
      if (currentIndex <= text.length) {
        setDisplayedText(text.slice(0, currentIndex));
        currentIndex++;
      } else {
        setIsDone(true);
        clearInterval(interval);
      }
    }, 28);

    return () => clearInterval(interval);
  }, [isTyping, isDone, text]);

  return (
    <p ref={containerRef} className={className}>
      {displayedText}
      {!isDone && (
        <span className="inline-block w-[3px] h-[1em] bg-[#00a3e0] ml-1 translate-y-[2px] animate-pulse" />
      )}
    </p>
  );
}

