function Frame55() {
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.defaultMuted = true;
      videoRef.current.muted = true;
      videoRef.current.play().catch(() => {});
    }
  }, []);

  return (
    <div className="bg-[#fffaf8] overflow-hidden relative rounded-none shrink-0 w-full flex items-center justify-center border-none outline-none shadow-none">
      <video
        ref={videoRef}
        src={videoAuraVideo}
        autoPlay
        loop
        muted
        playsInline
        preload="auto"
        onTimeUpdate={() => {
          if (videoRef.current && videoRef.current.duration) {
            if (videoRef.current.currentTime >= videoRef.current.duration - 0.12) {
              videoRef.current.currentTime = 0;
              videoRef.current.play().catch(() => {});
            }
          }
        }}
        onEnded={() => {
          if (videoRef.current) {
            videoRef.current.currentTime = 0;
            videoRef.current.play().catch(() => {});
          }
        }}
        style={{ outline: "none", border: "none", boxShadow: "none" }}
        className="w-full h-auto object-cover pointer-events-none select-none border-none outline-none shadow-none block rounded-none"
      />
    </div>
  );
}

