function Frame178() {
  const [currentSlide, setCurrentSlide] = useState(0);

  const slides = [
    {
      title: "Difficult Conversations",
      tag: "Use Case 01",
      component: <Frame176 />,
    },
    {
      title: "Social Anxiety Relief",
      tag: "Use Case 02",
      component: <Frame179 />,
    },
    {
      title: "Burnout Firewall",
      tag: "Use Case 03",
      component: <Frame182 />,
    },
  ];

  const prevSlide = () => {
    setCurrentSlide((prev) => (prev === 0 ? slides.length - 1 : prev - 1));
  };

  const nextSlide = () => {
    setCurrentSlide((prev) => (prev === slides.length - 1 ? 0 : prev + 1));
  };

  return (
    <div className="flex flex-col gap-6 w-full relative">
      {/* Carousel Navigation Tabs & Controls Header */}
      <div className="flex items-center justify-between gap-4 w-full border-b border-gray-100 pb-4">
        {/* Tab Pills */}
        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar">
          {slides.map((slide, idx) => (
            <button
              key={idx}
              onClick={() => setCurrentSlide(idx)}
              className={`px-4 py-2 rounded-full text-xs font-semibold transition-all duration-300 cursor-pointer whitespace-nowrap ${
                currentSlide === idx
                  ? "bg-black text-white shadow-xs"
                  : "bg-gray-100 text-gray-600 hover:bg-gray-200"
              }`}
            >
              <span className="opacity-60 mr-1.5">{slide.tag}</span>
              {slide.title}
            </button>
          ))}
        </div>

        {/* Arrow Buttons */}
        <div className="flex items-center gap-2 shrink-0">
          <button
            onClick={prevSlide}
            aria-label="Previous slide"
            className="w-9 h-9 rounded-full border border-gray-200 flex items-center justify-center text-gray-700 hover:bg-black hover:text-white hover:border-black transition-all cursor-pointer shadow-2xs font-bold"
          >
            ←
          </button>
          <button
            onClick={nextSlide}
            aria-label="Next slide"
            className="w-9 h-9 rounded-full border border-gray-200 flex items-center justify-center text-gray-700 hover:bg-black hover:text-white hover:border-black transition-all cursor-pointer shadow-2xs font-bold"
          >
            →
          </button>
        </div>
      </div>

      {/* Slide Content Container */}
      <div className="w-full transition-all duration-300 min-h-[480px]">
        {slides[currentSlide].component}
      </div>

      {/* Dot Indicators */}
      <div className="flex items-center justify-center gap-2 pt-2">
        {slides.map((_, idx) => (
          <button
            key={idx}
            onClick={() => setCurrentSlide(idx)}
            className={`h-2 rounded-full transition-all duration-300 cursor-pointer ${
              currentSlide === idx ? "w-8 bg-black" : "w-2 bg-gray-300 hover:bg-gray-400"
            }`}
            aria-label={`Go to slide ${idx + 1}`}
          />
        ))}
      </div>
    </div>
  );
}

